TRUNCATE TABLE PORTS;
TRUNCATE TABLE COMMODITIES;
TRUNCATE TABLE CONFLICTS;
TRUNCATE TABLE DISASTERS;
TRUNCATE TABLE SHIPMENTS;
TRUNCATE TABLE DISRUPTION_LOG;
SET FOREIGN_KEY_CHECKS = 1;

